mapper.select:
SELECT SQL_CALC_FOUND_ROWS gso.od_id, gso.od_time, gso.od_completion_date, gso.od_settle_case FROM g5_shop_order gso INNER JOIN g5_shop_cart gsc ON gso.od_id = gsc.od_id INNER JOIN g5_shop_item gsi ON gsc.it_id = gsi.it_id WHERE gso.mb_id = #{mbId}
AND gsc.it_name LIKE CONCAT('%', #{searchKeyword}, '%') AND gsc.it_id LIKE CONCAT('%', #{searchKeyword}, '%')
AND DATE_FORMAT(gso.od_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}
AND (gsc.ct_status = '반품')
AND (gsc.ct_status = '반품접수')
AND gsc.ct_status IN ('반품완료', '반품정산완료')
AND gsc.ct_status = #{ctStatus}
AND (gsc.ct_status = '취소' OR gsc.ct_status = '취소완료')
AND (gsc.ct_status IN ('반품', '반품접수','반품완료','반품정산완료'))
GROUP BY gso.od_id ORDER BY od_time DESC LIMIT #{pageNo}, #{pageSize};

SELECT gso.od_id, gso.od_time, gsc.it_name, gsc.it_id, gso.od_cart_count,od_cart_price, '택배배송' AS od_delivery_method, CASE WHEN gsc.ct_status = '반품' OR gsc.ct_status = '반품완료' THEN gsc.ct_status ELSE gso.od_status END AS od_status, gsc.ct_option, gsc.ct_qty, CASE WHEN gsi.it_img1 != '' THEN CONCAT(#{imageServerUri}, gsi.it_img1) ELSE NULL END AS it_img1, DENSE_RANK() OVER (ORDER BY gso.od_id DESC) AS row_num, gsc.ct_price, CASE WHEN ( SELECT COUNT(*) FROM g5_shop_item_use WHERE it_id = gsc.it_id AND od_id = gsc.od_id AND del_fl = 0 ) > 0 THEN 1 ELSE 0 END AS review_fl, CASE WHEN ( SELECT COUNT(*) FROM g5_shop_item_use WHERE it_id = gsc.it_id AND od_id = gsc.od_id AND del_fl = 0 AND STR_TO_DATE(SUBSTRING_INDEX(SUBSTRING_INDEX(gsc.ct_history, '|', -2), '|', 1), '%Y-%m-%d %H:%i:%s') >= DATE_SUB(CURDATE(), INTERVAL 15 DAY) AND gsc.ct_status = '완료' ) > 0 THEN 1 ELSE 0 END AS review_del_fl, gsc.ct_id, gsc.ct_status, gsc.pet_id, gsc.pet_history_id, gsc.urine_check_history_id, gso.od_cart_coupon, gso.od_send_cost, gso.od_send_cost2, gso.od_receipt_point, gso.od_invoice, IFNULL((SELECT io_price FROM g5_shop_item_option WHERE io_id = gsc.io_id LIMIT 1), 0) AS io_price, IFNULL((SELECT io_type FROM g5_shop_item_option WHERE io_id = gsc.io_id LIMIT 1), 0) AS io_type, pcc.code_nm AS od_delivery_company, gso.od_delivery_company AS delivery_company_code, gsc.refund_invoice, gsc.refund_company FROM g5_shop_order gso INNER JOIN g5_shop_cart gsc ON gso.od_id = gsc.od_id INNER JOIN g5_shop_item gsi ON gsc.it_id = gsi.it_id LEFT JOIN pet_common_code pcc ON gso.od_delivery_company = pcc.code_cd WHERE gso.mb_id = #{mbId} AND gso.od_id = #{odId}
AND gsc.it_name LIKE CONCAT('%', #{searchKeyword}, '%') AND gsc.it_id LIKE CONCAT('%', #{searchKeyword}, '%')
AND DATE_FORMAT(gso.od_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}
AND (gsc.ct_status = '반품')
AND (gsc.ct_status = '반품접수')
AND gsc.ct_status IN ('반품완료', '반품정산완료')
AND gsc.ct_status = #{ctStatus}
AND (gsc.ct_status = '취소' OR gsc.ct_status = '취소완료')
AND (gsc.ct_status = '반품' OR gsc.ct_status = '반품접수' OR gsc.ct_status = '반품완료' OR gsc.ct_status = '반품정산완료')
ORDER BY od_time DESC

SELECT cp_no, cp_id, cp_subject, cp_method, cp_target, cz_id, cp_start, cp_end,
       cp_price, cp_type, cp_trunc, cp_minimum, cp_maximum, od_id, cp_datetime
FROM g5_shop_coupon c
WHERE mb_id IN (#{mbId}, '전체회원')
  AND cp_start <= CURDATE()
  AND cp_end >= CURDATE()
  AND NOT EXISTS (
    SELECT 1 FROM g5_shop_coupon_log l
    WHERE l.cp_id = c.cp_id
  )
  AND (cp_target IN (
    SELECT CASE WHEN c.cp_method = 1 THEN gsi.ca_id ELSE gsi.it_id END FROM g5_shop_cart gsc INNER JOIN g5_shop_item gsi ON gsc.it_id = gsi.it_id WHERE gsc.od_id = #{odId}
) OR cp_method IN (2, 3));

SELECT COUNT(*)
FROM g5_shop_cart
WHERE mb_id = #{mbId} AND ct_direct = 0 AND ct_status = '쇼핑' AND it_id = #{itId} AND io_id = #{ioId};

SELECT (SELECT SUM(CASE WHEN ct_status = '주문' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS od_count, (SELECT SUM(CASE WHEN ct_status = '입금' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS pay_count, (SELECT SUM(CASE WHEN ct_status = '준비' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS ready_count, (SELECT SUM(CASE WHEN ct_status = '배송' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS delivery_count, (SELECT SUM(CASE WHEN ct_status = '완료' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS end_count, (SELECT SUM(CASE WHEN ct_status = '취소' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS cancel_count, (SELECT SUM(CASE WHEN ct_status = '취소완료' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS cancel_finish_count, (SELECT SUM(CASE WHEN ct_status = '반품' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS back_count, (SELECT SUM(CASE WHEN ct_status = '반품접수' THEN 1 ELSE 0 END) FROM g5_shop_cart WHERE mb_id = #{mbId}) AS back_submit_count, (SELECT COUNT(*) FROM g5_shop_cart WHERE mb_id = #{mbId} AND ct_status IN ('반품완료','반품정산완료')) AS product_back_count, (SELECT COUNT(*) FROM g5_shop_coupon WHERE mb_id IN ('전체회원', #{mbId}) AND cp_id NOT IN (SELECT cp_id FROM g5_shop_coupon_log WHERE mb_id = #{mbId}) AND NOW() BETWEEN cp_start AND cp_end) AS coupon_count, (SELECT mb_point FROM g5_member WHERE mb_id = #{mbId}) AS mb_point, ( SELECT IFNULL(SUM(point_point), 0) FROM ( SELECT SUM(gsc.ct_point * gsc.ct_qty) AS point_point FROM g5_shop_cart gsc JOIN g5_shop_order gso ON gsc.od_id = gso.od_id WHERE gso.mb_id = #{mbId}
AND DATE_FORMAT(gso.od_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}
AND gso.od_status IN ('주문','입금','준비','배송')
UNION ALL
SELECT SUM(ROUND(CAST(gsi.it_price AS DECIMAL(20,4)) * (CAST(gsi.it_2 AS DECIMAL(5,2)) / 100) / 10) * 10) AS point_point FROM g5_shop_cart gsc JOIN g5_shop_order gso ON gsc.od_id = gso.od_id JOIN g5_shop_item gsi ON gsc.it_id = gsi.it_id WHERE gso.mb_id = #{mbId}
AND DATE_FORMAT(gso.od_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}
AND gso.od_status IN ('완료') AND gsi.it_2 IS NOT NULL AND gsi.it_2 != 0 AND gsc.it_id NOT IN ( SELECT it_id FROM g5_shop_item_use WHERE mb_id = #{mbId} AND del_fl = 0 GROUP BY it_id ) ) sub ) AS total_point

SELECT od_id
FROM g5_shop_cart
WHERE ct_id = #{ctId};

mapper.delete:
DELETE FROM g5_shop_cart
WHERE
mb_id = #{mbId} AND ct_direct = 1 AND ct_status = '쇼핑';

mapper.select:
SELECT SQL_CALC_FOUND_ROWS gsi.it_name, gsi.it_cust_price, gsi.it_price, (gsi.it_cust_price - gsi.it_price) / gsi.it_cust_price * 100 AS discount_amt, CONCAT(#{imageServerUri}, gsi.it_img1) AS prd_image, (SELECT CASE WHEN COUNT(it_id) > 0 THEN TRUE ELSE FALSE END FROM g5_shop_wish WHERE it_id = gsi.it_id AND mb_id = #{mbId}) AS is_liked, gsi.it_type1 AS hit_fl, gsi.it_type2 AS recommend_fl, gsi.it_type3 AS new_fl, gsi.it_type4 AS best_fl, gsi.it_use_avg, gsi.it_id, (SELECT COUNT(*) FROM g5_shop_item_use WHERE it_id = gsi.it_id AND del_fl = 0) AS item_count FROM g5_shop_item gsi WHERE gsi.it_use = 1
AND it_9 = #{petTypeCd}
AND (ca_id = #{caId} OR ca_id2 = #{caId})
AND gsi.it_type2 = 1
AND gsi.it_8 = #{regularItemType}
LIMIT #{pageNo}, #{pageSize};
